#!/bin/sh
# Atajos del laboratorio. Uso: ./lab.sh arrancar | parar | atacante | cortafuegos | servidor | alertas
cd "$(dirname "$0")"
case "$1" in
  arrancar)    docker compose up -d
               # si ya tienes Suricata preparado (experimento del IDS), lo arranca también
               [ -x scripts/ids-arrancar.sh ] && docker compose exec -T cortafuegos /lab/scripts/ids-arrancar.sh ;;
  parar)       docker compose down ;;
  atacante|cortafuegos|servidor) docker compose exec "$1" bash ;;
  alertas)     docker compose exec cortafuegos /lab/scripts/ids-alertas.sh ;;
  *) echo "Uso: ./lab.sh arrancar | parar | atacante | cortafuegos | servidor | alertas" ;;
esac
